name: Windows workspace archive

on:
  workflow_call:
    inputs:
      diagnostic_timing:
        type: boolean
        default: false

permissions:
  contents: read

env:
  CARGO_TERM_COLOR: never
  # Both producer and consumers keep the same ordinary Cargo profile inputs.
  CARGO_PROFILE_DEV_DEBUG: line-tables-only
  CARGO_PROFILE_TEST_DEBUG: line-tables-only
  RUST_TEST_THREADS: '1'
  MESH_TALK_TEST_TIMING: ${{ inputs.diagnostic_timing && '1' || '0' }}

jobs:
  build:
    name: Windows workspace build
    runs-on: windows-latest
    timeout-minutes: 60
    outputs:
      rust: ${{ steps.compiler.outputs.rust }}
    defaults:
      run:
        shell: bash
    steps:
      - name: Use runner-owned native temporary storage
        shell: pwsh
        run: |
          Write-Host "Native temporary storage: $([IO.Path]::GetTempPath()) -> $env:RUNNER_TEMP"
          "TEMP=$env:RUNNER_TEMP" >> $env:GITHUB_ENV
          "TMP=$env:RUNNER_TEMP" >> $env:GITHUB_ENV
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with:
          ref: ${{ github.sha }}
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1
        with:
          node-version: 22
          cache: npm
          cache-dependency-path: frontend/package-lock.json
      - name: Validate Windows native build dependencies
        run: node scripts/ci/windows-native-deps.mjs
      - uses: dtolnay/rust-toolchain@stable
        with:
          components: clippy, rustfmt, llvm-tools-preview
      - name: Pin producer compiler for consumers
        id: compiler
        run: rustc --version | awk '{print "rust=" $2}' >> "$GITHUB_OUTPUT"
      - uses: Swatinem/rust-cache@v2
        env:
          CARGO_TERM_COLOR: always
          RUST_TEST_THREADS: ''
        with:
          save-if: ${{ github.ref == 'refs/heads/main' }}
          workspaces: . -> target
          shared-key: workspace-checks-checks
          cache-on-failure: true
      - name: Frontend dependencies and structural checks
        run: |
          npm ci --prefix frontend
          node scripts/validation/standards.mjs
          node scripts/check-repository-hygiene.mjs
      - uses: taiki-e/install-action@v2.87.31
        with:
          tool: cargo-nextest@0.9.150,cargo-llvm-cov@0.8.7
      - name: Validate archive and coverage contracts
        # Native environment probes and real Cargo fixtures belong to this
        # serial owner, outside the parallel portable diagnostic suite.
        run: node --test --test-concurrency=1 scripts/ci/windows-native-deps.test.mjs scripts/ci/backend-coverage.test.mjs scripts/ci/rust-profile.test.mjs scripts/ci/windows-coverage-cli.test.mjs scripts/diagnostics/windows-coverage.test.mjs
      - name: Build frontend
        working-directory: frontend
        run: |
          npm run build
          npm run check:build-syntax
      - name: Clippy
        run: cargo clippy --workspace --all-targets -- -D warnings
      - name: Build production workspace
        run: cargo build --workspace --locked
      - name: Workspace doctests
        run: cargo test --workspace --doc --locked
      - name: Build one instrumented workspace archive
        run: |
          eval "$(cargo llvm-cov show-env --sh)"
          node scripts/ci/windows-coverage.mjs produce "$RUNNER_TEMP/windows-workspace-archive"
      - name: Upload sealed workspace archive
        uses: actions/upload-artifact@v7
        with:
          name: windows-workspace-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}
          path: ${{ runner.temp }}/windows-workspace-archive/
          compression-level: 0
          if-no-files-found: error
          retention-days: 3

  tests:
    name: Windows workspace tests (${{ matrix.shard }}/8)
    needs: build
    runs-on: windows-latest
    timeout-minutes: 90
    strategy:
      fail-fast: false
      matrix:
        shard: [1, 2, 3, 4, 5, 6, 7, 8]
    defaults:
      run:
        shell: bash
    steps:
      - name: Use runner-owned native temporary storage
        shell: pwsh
        run: |
          Write-Host "Native temporary storage: $([IO.Path]::GetTempPath()) -> $env:RUNNER_TEMP"
          "TEMP=$env:RUNNER_TEMP" >> $env:GITHUB_ENV
          "TMP=$env:RUNNER_TEMP" >> $env:GITHUB_ENV
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with:
          ref: ${{ github.sha }}
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1
        with:
          node-version: 22
      - uses: dtolnay/rust-toolchain@stable
        with:
          toolchain: ${{ needs.build.outputs.rust }}
          components: llvm-tools-preview
      - uses: taiki-e/install-action@v2.87.31
        with:
          tool: cargo-nextest@0.9.150,cargo-llvm-cov@0.8.7
      # No Cargo cache, dependency fetch, frontend rebuild or test compilation.
      - uses: actions/download-artifact@v8
        with:
          name: windows-workspace-${{ github.sha }}-${{ github.run_id }}-${{ github.run_attempt }}
          path: ${{ runner.temp }}/windows-workspace-archive
      - name: Run validated serial shard and export partial coverage
        env:
          CARGO_NET_OFFLINE: 'true'
          # Collect every selected case so one failure does not hide later defects.
          MESH_WINDOWS_FAIL_FAST: '0'
        run: |
          eval "$(cargo llvm-cov show-env --sh)"
          node scripts/ci/windows-coverage.mjs consume "${{ matrix.shard }}" "$RUNNER_TEMP/windows-workspace-archive" "$RUNNER_TEMP/windows-workspace-results"
      - name: Preserve inventory, execution receipt and coverage
        if: always()
        uses: actions/upload-artifact@v7
        with:
          name: windows-workspace-results-${{ matrix.shard }}-${{ github.run_attempt }}
          path: ${{ runner.temp }}/windows-workspace-results/
          if-no-files-found: error
          retention-days: 14
      - name: Upload validated partial coverage to Codecov
        if: >-
          !(github.event_name == 'pull_request' &&
            github.base_ref == 'dev' &&
            github.event.pull_request.user.login == 'dependabot[bot]')
        uses: codecov/codecov-action@303a32d7a59b442fa8d48b6a1cc6825c09c847a5
        with:
          token: ${{ secrets.CODECOV_TOKEN }}
          files: ${{ runner.temp }}/windows-workspace-results/coverage.lcov
#!/usr/bin/env node
// Official nextest archives, fixed source paths, serial hash shards and receipts.
// Pinned LLVM coverage uses v1 target/debug/{deps,examples}; see upstream #520.
import assert from "node:assert/strict";
import { spawn, spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { appendFileSync, closeSync, createReadStream, existsSync, mkdirSync, openSync, readFileSync, rmSync, writeFileSync, writeSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const versions = Object.freeze({ nextest: "0.9.150", llvmCov: "0.8.7" });
export const windowsPartitions = Object.freeze([1, 2, 3, 4, 5, 6, 7, 8]);
const buildArgs = ["--workspace", "--locked"];
const nextestArgs = ["--profile", "default", "--user-config-file", "none"];
const canonical = value => JSON.stringify(value);
const digest = data => createHash("sha256").update(data).digest("hex");
const readJson = file => JSON.parse(readFileSync(file, "utf8"));
const writeJson = (file, value) => writeFileSync(file, `${JSON.stringify(value, null, 2)}\n`);
async function fileHash(file) {
  const hash = createHash("sha256");
  for await (const chunk of createReadStream(file)) hash.update(chunk);
  return hash.digest("hex");
}
export async function command(args, { env = process.env, receipt, progress, phase = "command", liveStdout = false, binary = "cargo", signal, maxOutputBytes = 128 * 1024 * 1024 } = {}) {
  assert.ok(Number.isSafeInteger(maxOutputBytes) && maxOutputBytes > 0 && maxOutputBytes <= 128 * 1024 * 1024, "Invalid CI command output limit");
  const record = event => {
    if (progress) appendFileSync(progress, `${JSON.stringify({ at: new Date().toISOString(), phase, ...event })}\n`);
  };
  const files = [];
  try {
    if (receipt) {
      files.push(openSync(`${receipt}.jsonl`, "w"));
      files.push(openSync(`${receipt}.log`, "w"));
    }
    // Publish the phase before starting the child; cancellation must not erase
    // whether a shard was listing tests, running them, or reporting coverage.
    record({ event: "started", binary, args });
    signal?.throwIfAborted();
    return await new Promise((resolve, reject) => {
      const child = spawn(binary, args, { env, windowsHide: true, detached: process.platform !== "win32", stdio: ["ignore", "pipe", "pipe"] });
      const output = [];
      const bytes = [0, 0];
      let failure, stopping = false, outputRejected = false;
      let cleanup = Promise.resolve();
      const stop = error => {
        failure ??= error;
        if (stopping || !child.pid) return;
        stopping = true;
        if (process.platform === "win32") {
          cleanup = new Promise(done => {
            const killer = spawn("taskkill.exe", ["/PID", String(child.pid), "/T", "/F"], { windowsHide: true, stdio: "ignore" });
            killer.on("error", error => { failure = error; child.kill(); });
            killer.on("close", code => {
              if (code !== 0) { failure = new Error("Windows child-tree termination could not be verified"); child.kill(); }
              done();
            });
          });
        } else {
          try { process.kill(-child.pid, "SIGTERM"); } catch (error) { if (error.code !== "ESRCH") failure = error; }
          // As in the validation stage owner, finish group cleanup even when
          // the leader exits before a descendant with independent stdio.
          cleanup = new Promise(done => setTimeout(() => {
            try { process.kill(-child.pid, "SIGKILL"); } catch (error) { if (error.code !== "ESRCH") failure = error; }
            done();
          }, 2000));
        }
      };
      const interrupted = () => stop(new Error("CI command interrupted"));
      process.on("SIGINT", interrupted);
      process.on("SIGTERM", interrupted);
      signal?.addEventListener("abort", interrupted, { once: true });
      if (signal?.aborted) interrupted();
      child.on("spawn", () => {
        try { record({ event: "spawned", pid: child.pid }); } catch (error) { stop(error); }
      });
      const capture = (index, chunk) => {
        if (outputRejected) return;
        try {
          assert.ok(chunk.length <= maxOutputBytes - bytes[index], "CI command output exceeded its byte limit");
          if (files[index] !== undefined) {
            let written = 0;
            while (written < chunk.length) {
              const count = writeSync(files[index], chunk, written, chunk.length - written);
              assert.ok(count > 0, "CI command receipt write made no progress");
              written += count;
            }
          }
          if (index === 1) process.stderr.write(chunk);
          else if (liveStdout) process.stdout.write(chunk);
          bytes[index] += chunk.length;
          if (index === 0) output.push(chunk);
        } catch (error) { outputRejected = true; stop(error); }
      };
      child.stdout.on("data", chunk => capture(0, chunk));
      child.stderr.on("data", chunk => capture(1, chunk));
      child.on("error", stop);
      child.on("close", async (code, childSignal) => {
        await cleanup;
        process.off("SIGINT", interrupted);
        process.off("SIGTERM", interrupted);
        signal?.removeEventListener("abort", interrupted);
        try {
          record({ event: "closed", code, signal: childSignal, stdoutBytes: bytes[0], stderrBytes: bytes[1], failed: !!failure || code !== 0 });
          if (failure) throw failure;
          assert.equal(code, 0, `${binary} ${args.join(" ")} failed: ${code}/${childSignal}`);
          resolve(Buffer.concat(output).toString("utf8"));
        } catch (error) { reject(error); }
      });
    });
  } finally {
    for (const file of files) closeSync(file);
  }
}
function tool(binary, args) {
  const result = spawnSync(binary, args, { encoding: "utf8" });
  assert.ok(!result.error && result.status === 0, `${binary} ${args.join(" ")} failed`);
  return result.stdout.trim();
}

export function inventory(listing) {
  const rows = [];
  assert.ok(listing["rust-suites"] && Number.isInteger(listing["test-count"]), "Invalid nextest inventory");
  for (const [binaryId, suite] of Object.entries(listing["rust-suites"])) {
    assert.equal(suite.status, "listed", `Unlisted test binary: ${binaryId}`);
    for (const [name, test] of Object.entries(suite.testcases)) {
      assert.equal(test.kind, "test", "Unsupported benchmark/custom test kind");
      assert.equal(typeof test.ignored, "boolean", "Missing ignored marker");
      assert.ok(["matches", "mismatch"].includes(test["filter-match"]?.status), "Missing filter result");
      rows.push({ id: `${binaryId}::${name}`, eventName: `${suite["package-name"]}::${suite["binary-name"]}$${name}`, ignored: test.ignored, selected: test["filter-match"].status === "matches" });
    }
# Project-wide resource limits to keep cargo from saturating the CPU.
#
# Rationale: cargo sizes both compilation and test parallelism to the number of
# CPU cores by default, which pins all cores. (Test builds use cheap KDF params via
# cfg(test)/the fast-test-kdf feature, so the suite is no longer KDF-bound — but a
# full parallel compile can still saturate a small machine.) These caps apply to
# EVERY cargo invocation in this tree (CI, contributors, and AI sessions) automatically.
#
# Tuned for an 8-core machine at a "gentle" ~half-cores level. Adjust the two
# numbers if you change machines.

[build]
# Cap parallel compilation units (codegen jobs). ~half of logical cores.
jobs = 4

[env]
# Cap libtest's parallel test threads so the suite doesn't pin every core at once.
# Honored by the test harness produced by `cargo test`.
RUST_TEST_THREADS = "4"
debug = "none"
incremental = true

# Keep the default speed-oriented opt-level while reducing duplicate native code and
# shipping symbols. Thin LTO limits release build time compared with fat LTO.
[profile.release]
lto = "thin"
codegen-units = 1
strip = "symbols"

# The Tauri shell dominates local release rebuilds. Split only this crate's
# code generation across cores; keep dependencies and the protocol core at one
# unit for their existing release-size/runtime trade-off. Thin LTO and symbol
# stripping still apply to the final app.
[profile.release.package.mesh-talk]
codegen-units = 4

# Dev-build ergonomics: full-strength Argon2/PBKDF2 are unbearably slow in an unoptimized
# debug build — `tauri dev` keystore unlock ("unlocking your encrypted stores") can take
# minutes and looks like a hang. Optimize crypto dependencies so unlock is fast;
# most application crates keep default debug optimization for incremental builds.
# KDF parameters stay unchanged, so existing keystores decrypt. Release builds are unaffected.
[profile.dev.package.argon2]
opt-level = 3
[profile.dev.package.blake2]
opt-level = 3
[profile.dev.package.pbkdf2]
opt-level = 3
[profile.dev.package.sha2]
opt-level = 3
[profile.dev.package.hmac]
opt-level = 3
[profile.dev.package.aes-gcm]
opt-level = 3
[profile.dev.package.aes]
opt-level = 3

# Noise uses curve25519 v4; identity/presence signatures use v5. Optimize both
# debug-build implementations without changing algorithms, checks, or release builds.
[profile.dev.package."curve25519-dalek:4.1.3"]
opt-level = 3
[profile.dev.package."curve25519-dalek:5.0.0"]
opt-level = 3

# AEAD generic loops are instantiated in the protocol caller, so dependency-only
# optimization leaves large encrypted document pages CPU-bound in debug tests.
# Keep debug assertions and overflow checks while optimizing this caller modestly.
# Test and mutation profiles inherit this; release settings remain independent.
[profile.dev.package.mesh-talk-core]
opt-level = 1
